from decimal import Decimal
from fractions import Fraction
from typing import Any


def _numeric(value: Any) -> Fraction:
    """Apply legacy NVL/empty-string numeric coercion without binary floats."""
    if value is None:
        return Fraction(0)

    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return Fraction(0)

    if isinstance(value, bool):
        return Fraction(int(value))

    if isinstance(value, Fraction):
        return value

    if isinstance(value, Decimal):
        return Fraction(value)

    if isinstance(value, int):
        return Fraction(value)

    # str(float) preserves the caller-visible decimal value rather than the
    # float's binary expansion.
    return Fraction(Decimal(str(value)))


def _primary_key(row: dict) -> str:
    """ACCT_ID and ORD_ID are legacy character primary keys."""
    value = row.get("ACCT_ID", row.get("ORD_ID", ""))
    return "" if value is None else str(value)


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list[tuple[str, Any]]]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    account_indexes = sorted(
        range(len(new_accounts)),
        key=lambda index: _primary_key(new_accounts[index]),
    )
    ordered_orders = sorted(orders, key=_primary_key)

    for index in account_indexes:
        account = new_accounts[index]

        if account.get("DEL_FLG", "") == "Y":
            continue
        if account.get("ACCT_TYP", "") != "C":
            continue

        account_id = account.get("ACCT_ID", "")
        exposure = Fraction(0)

        for order in ordered_orders:
            if order.get("DEL_FLG", "") == "Y":
                continue
            if order.get("ACCT_ID", "") != account_id:
                continue
            if order.get("STAT_CD", "") == "I":
                exposure += _numeric(order.get("TOT_AMT", ""))

        credit_limit = _numeric(account.get("CRED_LIMIT", ""))

        if exposure > credit_limit and account.get("CRED_HOLD", "") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        # This is deliberately a separate IF and observes the update above.
        if (
            exposure <= credit_limit * Fraction(8, 10)
            and account.get("CRED_HOLD", "") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
